import {coupledOutage,weatherCapacity,densityRetrofit,stalledJob,phaseAcceptance} from './integrated-cases-model.js';
const n=(value,digits=1)=>Number(value.toFixed(digits)).toLocaleString('en-US');
const metric=(value,label,tone='')=>`<div class="i-metric ${tone}"><strong>${value}</strong><span>${label}</span></div>`;
const result=(html,tone='')=>`<div class="i-result ${tone}">${html}</div>`;
const note=html=>`<p class="i-inputs">${html}</p>`;
const svg=(label,body,view='0 0 1120 330')=>`<svg viewBox="${view}" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg"><defs><marker id="i-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="context-stroke"/></marker></defs>${body}</svg>`;
const text=(x,y,label,cls='')=>`<text x="${x}" y="${y}" class="${cls}" text-anchor="middle">${label}</text>`;
const line=(x1,y1,x2,y2,cls='power')=>`<path class="i-wire ${cls}" d="M${x1} ${y1}L${x2} ${y2}" marker-end="url(#i-arrow)"/>`;
const box=(x,y,w,h,label,sub='',cls='')=>`<g class="i-machine ${cls}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="9"/>${text(x+w/2,y+h/2-(sub?6:-7),label)}${sub?text(x+w/2,y+h/2+25,sub,'small'):''}</g>`;
const rack=(x,y)=>`<g class="i-rack"><rect x="${x}" y="${y}" width="104" height="138" rx="5"/>${[16,47,78,109].map(d=>`<rect x="${x+12}" y="${y+d}" width="80" height="17" rx="3"/>`).join('')}</g>`;
const stack=(...items)=>`<div class="i-stack">${items.join('')}</div>`;
const metrics=(...items)=>`<div class="i-metrics">${items.join('')}</div>`;
const responsiveDiagram=(wide,narrow)=>`<div class="i-diagram"><div class="i-wide">${wide.replaceAll('i-arrow','i-arrow-wide')}</div><div class="i-narrow">${narrow.replaceAll('i-arrow','i-arrow-narrow')}</div></div>`;

function wholeSystem(close=false){const wide=svg('Electrical energy reaches racks; information supports useful work; rack heat passes through cooling to the outdoors.',
 box(10,103,170,95,'Electricity','watts in')+line(183,150,367,150)+rack(405,80)+rack(526,80)+text(512,253,'Compute + network')+
 box(384,0,256,48,'Information')+line(512,49,512,77,'information')+
 line(632,150,795,150,'information')+box(805,101,300,95,close?'Useful work':'Accepted service',close?'correct output on time':'under stated conditions')+
 `<path class="i-wire heat" d="M514 270L514 302L907 302" marker-end="url(#i-arrow)"/>`+text(702,284,'Heat → outdoors','heat-label')+
 text(272,118,close?'Available power':'Outage','small')+text(702,122,close?'Working paths':'Network delay','small')+text(250,308,close?'Defined boundary':'Weather · density · handover','small'));
 const narrow=svg('Electricity and data enter compute; useful work leaves on the information path and heat leaves through cooling.',box(84,5,232,70,'Electricity','watts in')+line(200,78,200,113)+rack(148,122)+text(200,291,'Compute + network')+box(5,143,113,83,'Data','inputs')+line(120,185,143,185,'information')+line(200,303,200,337,'information')+box(69,343,262,79,close?'Useful work':'Accepted service','correct output on time')+`<path class="i-wire heat" d="M260 195H369V493H316" marker-end="url(#i-arrow)"/>`+box(85,455,229,78,'Heat outdoors')+text(200,573,close?'Every path must meet':'Five changes. One system.','small'),'0 0 400 600');
 return responsiveDiagram(wide,narrow);
}

function outagePath(protectedPump=false){const wide=svg('IT is supported by a battery. The facility-loop pump loses power unless its supply is moved to the battery. Heat must still reach outdoor rejection.',
 box(8,32,215,95,'Battery + inverter','2.5 MW')+line(225,80,395,80)+rack(424,15)+text(475,189,'2 MW IT')+
 box(8,220,215,90,protectedPump?'Protected bus':'Utility bus',protectedPump?'0.2 MW cooling':'Supply lost',protectedPump?'':'off')+
 (protectedPump?`<path class="i-wire power" d="M116 128V215" marker-end="url(#i-arrow)"/>`:'')+
 line(225,263,620,263,protectedPump?'power':'broken')+
 box(636,220,200,88,'Facility pump',protectedPump?'Supply survives':'Pump stopped',protectedPump?'':'off')+
 line(531,83,690,83,'heat')+box(702,36,150,94,'Heat loop')+line(858,83,918,83,'heat')+box(929,36,181,94,'Outdoors')+
 `<path class="i-wire heat ${protectedPump?'':'broken'}" d="M737 218V135" marker-end="url(#i-arrow)"/>`+text(948,265,'Flow + limits?','heat-label'));
 const narrow=svg('Battery supports IT. The separate pump bus is lost unless moved to the battery. Thermal support needs observed flow and temperatures.',box(10,15,190,86,'Battery','2.5 MW inverter')+line(203,58,259,58)+rack(271,8)+text(323,177,'2 MW IT')+box(10,222,184,85,protectedPump?'Protected bus':'Utility bus',protectedPump?'0.2 MW cooling':'Supply lost',protectedPump?'':'off')+(protectedPump?line(101,104,101,216):'')+line(196,265,224,265,protectedPump?'power':'broken')+box(229,222,164,85,'Pump',protectedPump?'Powered':'Stopped',protectedPump?'':'off')+`<path class="i-wire heat" d="M323 184V201H205V353" marker-end="url(#i-arrow)"/>`+box(105,360,200,82,'Heat loop','Flow + limits?')+line(205,448,205,489,'heat')+box(105,494,200,78,'Outdoors'),'0 0 400 590');
 return responsiveDiagram(wide,narrow);
}

function limits(m){return `<div class="i-limits">${[['Electrical',m.electricalMW],['Heat removal',m.coolingMW],['Accepted paths',m.pathMW]].map(([name,value])=>`<div><span>${name}</span><div class="i-limit-track"><i style="width:${Math.min(100,value)}%" class="${value===m.capacityMW?'binding':''}"></i></div><b>${n(value)} MW</b></div>`).join('')}</div>`}
function floorplan(architecture='b',route='blocked'){
 const blocked=architecture==='b'&&route==='blocked';
 const wide=svg('Room plan with a UPS module removal route. A sidecar in the service bay blocks the route; the revised position clears it.',
 `<rect class="i-room" x="35" y="15" width="1050" height="298" rx="8"/>`+
 box(65,44,190,115,'Existing UPS','module exits ↓')+
 `<path class="i-removal ${blocked?'blocked':''}" d="M160 162V265H1055" marker-end="url(#i-arrow)"/>`+
 rack(556,52)+rack(696,52)+text(675,218,'120 kW DC load')+
 (architecture==='b'?box(route==='blocked'?301:860,route==='blocked'?202:57,150,85,'Sidecar','AC → DC',blocked?'off':''):'')+
 text(600,294,blocked?'Removal route blocked':'UPS removal route clear',blocked?'heat-label':'')+
 text(1080,210,'Exit','small')+
 text(387,87,architecture==='a'?'A · conversion':'B · near-load', 'small')+text(387,114,architecture==='a'?'inside rack':'conversion','small'));
 const narrow=svg('Room plan: UPS removal follows the left aisle to the exit; a sidecar in that aisle blocks removal.',`<rect class="i-room" x="5" y="5" width="390" height="490" rx="8"/>`+box(25,30,171,88,'Existing UPS','module exits ↓')+`<path class="i-removal ${blocked?'blocked':''}" d="M107 128V446H357" marker-end="url(#i-arrow)"/>`+rack(248,33)+text(300,203,'120 kW DC')+(architecture==='b'?box(route==='blocked'?24:235,route==='blocked'?238:249,150,85,'Sidecar','AC → DC',blocked?'off':''):'')+text(209,392,blocked?'Removal route blocked':'Removal route clear',blocked?'heat-label':'')+text(357,482,'Exit','small'),'0 0 400 510');
 return responsiveDiagram(wide,narrow);
}

function jobPath(upgrade='none',show=false){const m=stalledJob({upgrade});const wide=svg('Sender to fabric bottleneck to receiver; the smallest achieved payload rate determines communication time.',
 rack(26,84)+text(78,261,'Sender')+box(290,112,206,96,'Fabric switch')+box(649,112,206,96,'Fabric switch')+rack(980,84)+text(1032,261,'Receiver')+
 line(134,152,282,152)+line(504,152,641,152,upgrade==='fabric'?'power':'heat')+line(865,152,973,152)+
 text(209,116,`${m.rates.sender} GB/s`)+text(574,116,`${m.rates.fabric} GB/s`)+text(924,116,`${m.rates.receiver} GB/s`)+
 text(561,35,'800 GB payload · one serial communication phase')+
 text(561,292,show?`${n(m.communicationSeconds)} s across the path`:'Predict the end-to-end transfer time','large'));
 const narrow=svg('The same 800 GB payload crosses the sender, fabric and receiver; compare each achieved payload-rate limit.',box(91,12,218,78,'Sender',`${m.rates.sender} GB/s`)+line(200,96,200,136)+box(91,142,218,75,'Fabric switch')+line(200,224,200,315,upgrade==='fabric'?'power':'heat')+text(288,275,`${m.rates.fabric} GB/s`)+box(91,321,218,75,'Fabric switch')+line(200,402,200,447)+box(91,453,218,78,'Receiver',`${m.rates.receiver} GB/s`)+text(200,575,'800 GB payload')+text(200,612,show?`${m.communicationSeconds} s transfer`:'Predict transfer time'),'0 0 400 630');
 return responsiveDiagram(wide,narrow);
}
function cycle(seconds,label){const total=60+seconds+10;return `<div class="i-cycle"><div class="i-cycle-label"><b>${label}</b><strong>${total} s</strong></div><div class="i-cycle-track"><span class="compute" style="flex:60">Compute<br><b>60 s</b></span><span class="communicate" style="flex:${seconds}">Network<br><b>${seconds} s</b></span><span class="other" style="flex:10">Other<br><b>10 s</b></span>${total<90?'<span class="saved" style="flex:10">10 s<br>saved</span>':''}</div></div>`}
function groups(m){return `<div class="i-groups">${m.groups.map(group=>`<section class="i-group ${group.accepted?'accepted':'held'}"><div class="i-group-roof"></div><div class="i-group-body"><b>${group.id}</b><div class="i-mini-racks" aria-hidden="true">${Array.from({length:4},()=>'<i></i>').join('')}</div><strong>${group.racks} racks</strong><span>${group.accepted?'Complete paths accepted':group.id==='B'?'Network acceptance open':'Cooling acceptance open'}</span></div></section>`).join('')}</div>`}
function schedule(failed){const end=failed?12:7;return `<div class="i-schedule"><div class="i-days"><span>Day 0</span><span>Day 12</span></div><div class="i-schedule-lane"><b>B</b><div><span style="flex:4">Interface work<br><strong>4 days</strong></span><span class="test" style="flex:2">Test<br><strong>2</strong></span><i style="flex:6"></i></div><em>Day 6</em></div><div class="i-schedule-lane"><b>C</b><div><span style="flex:3">Delivery<br><strong>3 days</strong></span><span style="flex:1">Fit<br><strong>1</strong></span><span class="test ${failed?'failed':''}" style="flex:3">Test<br><strong>3 days</strong></span>${failed?'<span class="correction" style="flex:2">Correct<br><strong>2</strong></span><span class="test" style="flex:3">Retest<br><strong>3 days</strong></span>':'<i style="flex:5"></i>'}</div><em>Day ${end}</em></div></div>`}

export function integratedCasesVisual(id,state){
 switch(id){
 case 'five-decisions':return stack(wholeSystem(),result('Choose what changes. Predict the consequence. Name the evidence.'));
 case 'outage-brief':return stack(outagePath(),metrics(metric('600 kWh','usable DC storage'),metric('90%','discharge efficiency'),metric('12 min','full restoration sequence')),note('IT transfer meets its interruption limit · controller stays powered · thermal inventory and limits unknown'));
 case 'outage-choice':{const m=coupledOutage({plan:state.outagePlan});return stack(outagePath(m.pumpSupplySurvives),state.outageReveal?metrics(metric(`${n(m.supportedMW)} MW`,'supported electrical load'),metric(`${n(m.idealMinutes,2)} min`,'ideal electrical duration'),metric(m.pumpSupplySurvives?'Supply repaired':'Pump still off','Thermal survival still needs evidence',m.pumpSupplySurvives?'':'warning')):result('Predict both: the electrical duration and the pump supply.','pending'),note(`${m.energyDC} kWh DC · 90% discharge efficiency · 2.5 MW inverter`));}
 case 'outage-timeline':return stack(`<div class="i-timeline"><div><b>IT electricity</b><span class="i-duration"><i></i><em>16.2 min ideal</em></span></div><div><b>Heat removal</b><span class="i-unknown">Pump off → thermal limit unknown</span></div><div class="i-ticks"><span>0 · utility lost</span><span>10 · generator</span><span>12 · full restoration</span></div></div>`,metrics(metric('540 kWh','AC energy available'),metric('400 kWh','12-minute IT requirement'),metric('140 kWh','electrical reserve')),result('The remaining energy cannot establish the missing thermal bridge.','warning'));
 case 'outage-evidence':return stack(`<div class="i-test-path"><section><div class="i-symbol">↯</div><h2>Supply → flow</h2><p>Auxiliary buses<br>Measured branch flow</p></section><span>→</span><section><div class="i-symbol heat">≈</div><h2>Flow → temperature</h2><p>Coolant and devices<br>Within transient limits</p></section><span>→</span><section><div class="i-symbol">✓</div><h2>Temperature → service</h2><p>Correct useful work<br>Through restoration</p></section></div>`,result('One disturbance test. Defined stop and acceptance criteria.'));
 case 'weather-brief':{const mild=weatherCapacity({weather:'mild'}),hot=weatherCapacity();return stack(`<div class="i-weather-pair"><section><h2>Mild operating point</h2>${limits(mild)}${metric('700 racks','70 MW IT envelope')}</section><section><h2>Hot operating point</h2>${limits(hot)}${metric('550 racks','55 MW IT envelope','warning')}</section></div>`,note('100 MW site ceiling · 100 kW/rack · same IT inlet requirement · auxiliaries fixed at 15 / 25 MW'));}
 case 'weather-choice':{const m=weatherCapacity({remedy:state.weatherRemedy});return stack(limits(m),state.weatherReveal?metrics(metric(`${m.racks} racks`,'supportable envelope'),metric(`${m.auxiliaryMW} MW`,'fixed auxiliary electricity'),metric(state.weatherRemedy==='auxiliaries'?'Energy saving':state.weatherRemedy==='cooling'?'+100 racks':'Cooling binds',state.weatherRemedy==='auxiliaries'?'No added rack capacity':'At this operating point')):result('Predict: energy saving, more capacity, or both?','pending'),note('Hot conditions · 900 accepted paths · cooling proposal keeps auxiliaries at 25 MW'));}
 case 'weather-paths':{const m=weatherCapacity({remedy:'cooling',acceptedRacks:state.acceptedRacks});return stack(limits(m),metrics(metric(`${m.racks} racks`,'complete supportable envelope'),metric(m.binding.includes('paths')?'Acceptance binds':'Cooling binds',`${n(m.capacityMW)} MW IT capacity`)),note('Hot conditions · 65 MW heat removal · 25 MW auxiliaries · 100 kW/rack'));}
 case 'weather-demand':{const m=weatherCapacity({remedy:'cooling',acceptedRacks:600,demandMW:state.demandMW});return stack(`<div class="i-energy-account"><div class="i-draw"><strong>${state.demandMW} MW</strong><span>IT demand</span></div><b>+</b><div class="i-draw auxiliaries"><strong>25 MW</strong><span>Auxiliaries</span></div><b>=</b><div class="i-draw total"><strong>${m.facilityMW} MW</strong><span>Facility draw</span></div></div>`,metrics(metric('60 MW','accepted IT capacity'),metric(`${60-state.demandMW} MW`,'unused IT capacity')),note('65 MW cooling · 600 accepted paths · supplied fixed auxiliary demand'));}
 case 'density-brief':return stack(floorplan(),metrics(metric('120 kW','same final DC load'),metric('160 kW','AC feeder limit'),metric('140 kW','whole-room heat limit')),note('A: 96% in-rack conversion · B: 97% sidecar × 98% near-load stage · all equipment inside room'));
 case 'density-ledger':{const m=densityRetrofit();return stack(`<div class="i-conversion"><div class="i-conversion-row"><b>A</b><section><strong>125 kW AC</strong><span>room input + heat</span></section><span class="i-stage">96% →</span><section><strong>120 kW DC</strong><span>declared load</span></section></div><div class="i-conversion-row b"><b>B</b><section><strong>126.24 kW AC</strong><span>room input + heat</span></section><span class="i-stage">97% →</span><section><strong>122.45 kW</strong><span>800 V DC · ${n(m.amps,2)} A</span></section><span class="i-stage">98% →</span><section><strong>120 kW DC</strong><span>same declared load</span></section></div></div>`,metrics(metric('5 kW','A conversion losses'),metric('6.24 kW','B conversion losses','warning')),note('B: 3.79 kW sidecar loss + 2.45 kW near-load loss · fixed efficiencies at this load'));}
 case 'density-choice':{const m=densityRetrofit({architecture:state.architecture});return stack(floorplan(state.architecture),state.densityReveal?metrics(metric(`${n(m.inputKW,2)} kW`,'AC input + room heat'),metric('Within limits','160 kW feeder · 140 kW cooling'),metric(m.accessPass?'Route clear':'Hold layout',m.accessPass?'A passes these three checks':'B blocks UPS removal',m.accessPass?'':'warning')):result('Predict the release decision across power, heat and maintenance.','pending'));}
 case 'density-route':{const m=densityRetrofit({architecture:'b',route:state.route});return stack(floorplan('b',state.route),metrics(metric('126.24 kW','input and room heat unchanged'),metric(m.accessPass?'Route hold closed':'Route hold remains','Then complete interface and migration acceptance',m.accessPass?'':'warning')));}
 case 'job-brief':return stack(cycle(20,'Serial job trace'),metrics(metric('800 GB','communication payload'),metric('40 GB/s','achieved path bottleneck'),metric('66.7%','useful-compute time share')),note('Same work each cycle · no phase overlap · ten seconds other work stays fixed'));
 case 'job-choice':{const m=stalledJob({upgrade:state.networkUpgrade});return stack(jobPath(state.networkUpgrade,state.networkReveal),state.networkReveal?metrics(metric(`${m.achievedGBps} GB/s`,'end-to-end payload rate'),metric(`${m.cycleSeconds} s`,'complete cycle'),metric(`${n(m.throughputRatio,3)}×`,'useful cycle throughput')):result('Predict the new communication phase and complete cycle.','pending'),note('60 s compute + communication + 10 s other work · supplied payload-rate limits'));}
 case 'job-consequence':return stack(cycle(20,'Existing path'),cycle(10,'Fabric bottleneck doubled'),metrics(metric('2×','communication rate'),metric('1.125×','useful cycle throughput')),note('90 / 80 = 1.125 · work per cycle and the other phases stay fixed'));
 case 'job-evidence':{const seconds=800/state.measuredRate;return stack(`<div class="i-probe"><div class="i-probe-payload"><span>Observed transfer</span><strong>800 GB ÷ ${state.measuredRate} GB/s</strong></div><span class="i-probe-arrow">→</span><div class="i-probe-reading"><strong>${seconds} s</strong><span>communication</span></div></div>`,cycle(seconds,'Aligned application trace'),result(state.measuredRate===80?'80-second cycle supports the prediction. Check correct output.':'The new link rating did not remove the observed bottleneck.',state.measuredRate===80?'':'warning'),note('Same payload · same work · compare the complete application trace'));
 }
 case 'phase-brief':return `<div class="i-campus"><figure><img src="../assets/references/distribution-abilene-data-halls.jpg" alt="Aerial of data halls and outdoor equipment at the original Abilene campus"><figcaption><a href="https://www.oracle.com/data-centers/" target="_blank" rel="noopener noreferrer">Oracle · Abilene data halls · 15 July 2026</a></figcaption></figure><div><h2>Return to Abilene</h2><p>Which phase has a complete accepted service path?</p><div class="i-case-boundary"><b>Next: original phase exercise</b><span>300 / 250 / 250 racks<br>Supplied handover register</span></div></div></div>`;
 case 'phase-choice':{const m=phaseAcceptance({open:state.open});return stack(note('Original phase exercise · 800 installed racks · 100 MW energized service · 100 kW/rack'),groups(m),state.openingReveal?result(m.canOpen?'Open A: 300 accepted racks = 30 MW of rack-equivalent demand.':`${m.requestedRacks} proposed racks include unaccepted paths. Open A; finish the held groups.`,m.canOpen?'':'warning'):result('Choose the opening scope. Identify the evidence that releases the rest.','pending'));}
 case 'phase-schedule':return stack(schedule(state.cTest==='fail'),metrics(metric('550 racks','after B passes on day 6'),metric(state.cTest==='fail'?'Day 12':'Day 7','earliest all-group acceptance if tests pass',state.cTest==='fail'?'warning':'')),note('Original schedule · separate qualified teams · all other resources and service paths available'));
 case 'phase-handover':{const m=phaseAcceptance({day:state.day,cTest:state.cTest});return stack(groups(m),metrics(metric(`${m.acceptedRacks} racks`,`${m.acceptedMW} MW accepted rack-equivalent demand`),metric('800 racks','installed inventory')),result(m.acceptedRacks===800?'Hand over the tested configuration, limits and operating ownership.':'Keep operating groups within their accepted conditions while work continues.'));}
 case 'watts-to-work':return stack(wholeSystem(true),result('Follow the power in, the heat out, and the information through.'));
 default:throw new Error(`Unknown integrated case scene: ${id}`);
 }
}
